xhtml:div.xhtml:script:
function openSite(url) {
  const win = window.open("about:blank", "_blank");

  if (!win) {
    alert("The browser blocked the new tab. Please allow pop-ups for this page.");
    return;
  }

  // Build the about:blank page.
  win.document.open();
  win.document.write(`
    <!DOCTYPE html>
    <html>
    <head>
      <meta charset="UTF-8">
      <title>Embedded Site</title>
      <style>
        html, body {
          margin: 0;
          width: 100%;
          height: 100%;
          overflow: hidden;
          background: #111;
        }

        iframe {
          width: 100%;
          height: 100%;
          border: 0;
          display: block;
        }
      </style>
    </head>
    <body>
      <iframe
        src="${url}"
        sandbox="allow-scripts allow-forms allow-same-origin"
        referrerpolicy="no-referrer">
      </iframe>
    </body>
    </html>
  `);
  win.document.close();
}
